import json

def guided_page(project_id=None):
    return HTML.replace("__PAYLOAD__",json.dumps(dict(project_id=project_id)).replace("<","\\u003c"))

def editor_page(html,phase):
    return html.replace("</body>","<script>"+COMMON.replace("__GUIDED_PHASE__",json.dumps(phase))+ADAPTERS[phase]+"</script></body>")

